CREATE OR REPLACE FUNCTION public.accept_workspace_invite(target_invite_id uuid, target_user_id uuid, target_email text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE invite_row public.workspace_invites%ROWTYPE; BEGIN SELECT * INTO invite_row FROM public.workspace_invites WHERE id = target_invite_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Invite not found'; END IF; IF invite_row.status <> 'pending' THEN IF invite_row.status = 'accepted' AND EXISTS (SELECT 1 FROM public.workspace_members WHERE workspace_id = invite_row.workspace_id AND user_id = target_user_id) THEN RETURN invite_row.workspace_id; END IF; RAISE EXCEPTION 'Invite is no longer valid'; END IF; IF invite_row.expires_at < now() THEN RAISE EXCEPTION 'Invite has expired'; END IF; IF lower(invite_row.email) <> lower(target_email) THEN RAISE EXCEPTION 'Invite email does not match authenticated user'; END IF; INSERT INTO public.workspace_members (workspace_id, user_id, role) VALUES (invite_row.workspace_id, target_user_id, invite_row.role) ON CONFLICT (workspace_id, user_id) DO NOTHING; UPDATE public.workspace_invites SET status = 'accepted' WHERE id = target_invite_id; RETURN invite_row.workspace_id; END; $$;